# update-ca-test-v2.ps1
Set-StrictMode -Off
$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'Create_Package.test.js')) {
    Write-Host 'ERROR: Run from Commercial Line Performance test folder' -ForegroundColor Red; exit 1
}

Write-Host 'Writing Create_CA.test.js...' -ForegroundColor Yellow
$b64 = ''
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path $PWD 'Create_CA.test.js'), $bytes)

node -c Create_CA.test.js
if ($LASTEXITCODE -eq 0) { Write-Host 'Syntax check PASSED' -ForegroundColor Green }
else { Write-Host 'Syntax check FAILED' -ForegroundColor Red; exit 1 }

git add Create_CA.test.js
git commit -m "CA: shared helpers, retry-loop clicks, remove redundant waits/dismissals, 30min timeout"
git push origin main

if ($LASTEXITCODE -eq 0) {
    Write-Host ''
    Write-Host 'Pushed. Test CA:' -ForegroundColor Green
    Write-Host '  $env:TEST_STATE="DE"; $env:TEST_ENV="qa"; $env:TEST_TYPE="CA"'
    Write-Host '  npx playwright test Create_CA.test.js --project=chromium --headed'
} else {
    Write-Host 'Push failed' -ForegroundColor Red
}
